"use client";

import React, { useState, useMemo } from "react";
import { 
  CalendarDays, MapPin, Filter, ChevronDown, 
  Globe, Sparkles, Flag
} from "lucide-react";

/* --- 1. DATASET (Enriched with numeric sort keys) --- */
const HOLIDAYS_DB = [
  // 2025
  { id: 1, name: "New Year's Day", date: "Jan 01", monthIdx: 0, day: "Wed", year: "2025", type: "Public", country: "Global", region: "All" },
  { id: 2, name: "Republic Day", date: "Jan 26", monthIdx: 0, day: "Sun", year: "2025", type: "National", country: "India", region: "All" },
  { id: 3, name: "Presidents' Day", date: "Feb 17", monthIdx: 1, day: "Mon", year: "2025", type: "Public", country: "USA", region: "All" },
  { id: 4, name: "Holi", date: "Mar 14", monthIdx: 2, day: "Fri", year: "2025", type: "Optional", country: "India", region: "North India" },
  { id: 5, name: "Good Friday", date: "Apr 18", monthIdx: 3, day: "Fri", year: "2025", type: "Public", country: "Global", region: "All" },
  
  // 2026
  { id: 6, name: "New Year's Day", date: "Jan 01", monthIdx: 0, day: "Thu", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 7, name: "Republic Day", date: "Jan 26", monthIdx: 0, day: "Mon", year: "2026", type: "National", country: "India", region: "All" },
  { id: 8, name: "Ugadi", date: "Mar 19", monthIdx: 2, day: "Thu", year: "2026", type: "Optional", country: "India", region: "Telangana" },
  { id: 9, name: "Memorial Day", date: "May 25", monthIdx: 4, day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },
  { id: 10, name: "Kannada Rajyotsava", date: "Nov 01", monthIdx: 10, day: "Sun", year: "2026", type: "Optional", country: "India", region: "Karnataka" },
  { id: 11, name: "Christmas", date: "Dec 25", monthIdx: 11, day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
];

const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

/* --- 2. LOCATION LOGIC --- */
const REGIONS_BY_COUNTRY: any = {
    "All": ["All", "Telangana", "Karnataka", "North India", "New York"],
    "India": ["All", "Telangana", "Karnataka", "North India"],
    "USA": ["All", "New York", "California"],
    "Global": ["All"]
};

export default function MonthWiseHolidayList() {
  const [year, setYear] = useState("2026");
  const [country, setCountry] = useState("All");
  const [region, setRegion] = useState("All");
  const [type, setType] = useState("All");

  // --- SMART FILTER & GROUPING LOGIC ---
  const groupedHolidays = useMemo(() => {
    // 1. Filter
    const filtered = HOLIDAYS_DB.filter((h) => {
      const matchYear = h.year === year;
      const matchCountry = country === "All" || h.country === country || h.country === "Global";
      const matchRegion = region === "All" || h.region === region || h.region === "All";
      const matchType = type === "All" || h.type === type;
      return matchYear && matchCountry && matchRegion && matchType;
    });

    // 2. Sort by Date
    filtered.sort((a, b) => a.monthIdx - b.monthIdx);

    // 3. Group by Month
    const groups: Record<string, typeof filtered> = {};
    filtered.forEach(h => {
        const monthKey = MONTH_NAMES[h.monthIdx];
        if (!groups[monthKey]) groups[monthKey] = [];
        groups[monthKey].push(h);
    });

    return groups;
  }, [year, country, region, type]);

  const handleCountryChange = (val: string) => {
      setCountry(val);
      setRegion("All");
  };

  return (
    <div className="min-h-screen bg-[#F8F9FC] dark:bg-[#030712] text-slate-900 dark:text-slate-100 font-sans p-6 lg:p-10">
      
      {/* --- HEADER & FILTERS --- */}
      <div className="max-w-5xl mx-auto mb-10">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end gap-6 border-b border-slate-200 dark:border-slate-800 pb-6">
            <div>
                <h1 className="text-3xl font-black uppercase tracking-tight text-slate-900 dark:text-white">
                    Holiday Calendar
                </h1>
                <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">
                    Fiscal Year {year} • {country === 'All' ? 'Global View' : country}
                </p>
            </div>

            <div className="flex flex-wrap gap-2 w-full lg:w-auto">
                <CompactSelect label="Year" value={year} onChange={setYear} options={['2025', '2026']} icon={<CalendarDays size={13} />} />
                <CompactSelect label="Country" value={country} onChange={handleCountryChange} options={['All', 'India', 'USA']} icon={<Flag size={13} />} />
                <CompactSelect label="Location" value={region} onChange={setRegion} options={REGIONS_BY_COUNTRY[country] || ['All']} disabled={country === 'Global'} icon={<MapPin size={13} />} />
                
                {/* Type Toggle */}
                <div className="bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-lg p-1 flex items-center h-[38px]">
                    {['All', 'Public', 'Optional'].map(t => (
                        <button key={t} onClick={() => setType(t)} className={`px-3 h-full rounded-md text-[9px] font-black uppercase tracking-widest transition-all ${type === t ? "bg-slate-900 text-white dark:bg-brand-600" : "text-slate-400 hover:text-slate-900 dark:hover:text-slate-200"}`}>
                            {t}
                        </button>
                    ))}
                </div>
            </div>
          </div>
      </div>

      {/* --- MONTH SECTIONS --- */}
      <div className="max-w-5xl mx-auto space-y-12">
        {Object.keys(groupedHolidays).length > 0 ? (
            Object.keys(groupedHolidays).map((month) => (
                <div key={month} className="animate-fade-in">
                    
                    {/* Month Header */}
                    <div className="flex items-center gap-4 mb-6">
                        <h2 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">
                            {month}
                        </h2>
                        <div className="h-[1px] flex-1 bg-slate-200 dark:bg-slate-800" />
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                            {groupedHolidays[month].length} Events
                        </span>
                    </div>

                    {/* Cards Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {groupedHolidays[month].map((h) => (
                            <HolidayCard key={h.id} data={h} />
                        ))}
                    </div>
                </div>
            ))
        ) : (
            <div className="py-20 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">No holidays match your filters.</p>
                <button onClick={() => { setCountry('All'); setType('All'); }} className="mt-2 text-xs text-brand-600 font-bold hover:underline">Reset Filters</button>
            </div>
        )}
      </div>
    </div>
  );
}

/* --- SUB-COMPONENTS --- */

const HolidayCard = ({ data }: { data: any }) => (
    <div className="group bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-xl p-4 flex items-center gap-4 hover:border-brand-500/40 transition-all hover:shadow-lg hover:shadow-brand-500/5 hover:-translate-y-0.5">
        
        {/* Date Box */}
        <div className="flex-shrink-0 w-12 h-12 bg-slate-50 dark:bg-white/5 rounded-lg flex flex-col items-center justify-center border border-slate-100 dark:border-white/5 group-hover:bg-brand-50 dark:group-hover:bg-brand-500/10 transition-colors">
            <span className="text-[8px] font-black uppercase text-slate-400">{data.day}</span>
            <span className="text-lg font-black text-slate-900 dark:text-white leading-none">{data.date.split(' ')[1]}</span>
        </div>

        {/* Info */}
        <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
                <Badge type={data.type} />
                <span className="text-[9px] font-black uppercase text-slate-400 truncate tracking-wide">
                     {data.country === 'Global' ? 'Global' : data.region}
                </span>
            </div>
            <h3 className="text-sm font-bold text-slate-900 dark:text-white truncate group-hover:text-brand-600 transition-colors">
                {data.name}
            </h3>
        </div>
    </div>
);

const Badge = ({ type }: { type: string }) => {
    const isOpt = type === 'Optional';
    return (
        <span className={`w-1.5 h-1.5 rounded-full ${isOpt ? 'bg-amber-500' : 'bg-emerald-500'}`} />
    );
};

const CompactSelect = ({ label, value, onChange, options, disabled, icon }: any) => (
    <div className={`relative bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-lg h-[38px] min-w-[130px] flex items-center ${disabled ? 'opacity-50 pointer-events-none' : ''}`}>
        <div className="absolute left-3 text-slate-400 pointer-events-none">{icon}</div>
        <select 
            value={value} 
            onChange={(e) => onChange(e.target.value)} 
            disabled={disabled}
            className="w-full h-full bg-transparent pl-9 pr-8 text-[10px] font-bold uppercase tracking-widest text-slate-700 dark:text-slate-200 outline-none cursor-pointer appearance-none rounded-lg hover:bg-slate-50 dark:hover:bg-white/5 transition-colors"
        >
            {options.map((opt: string) => <option key={opt} value={opt}>{opt}</option>)}
        </select>
        <ChevronDown size={12} className="absolute right-3 text-slate-300 pointer-events-none" />
    </div>
);